/**
 * Unit tests for scripts/generate-legal-content.js (MAINT-743 / TEST-34).
 *
 * Every filesystem effect is confined to an fs.mkdtempSync sandbox passed in through
 * main({ docsDir, outPath }). The real docs/legal/ and the real generated file are
 * never read or written. Fixtures are synthetic strings.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const {
  escapeForTemplateLiteral,
  main,
  SOURCES,
} = require('../../scripts/generate-legal-content');

// Test-only: evaluate the escaped text as a template literal body, exactly as the
// generated TypeScript module would.
const evalTemplate = (escaped) => new Function(`return \`${escaped}\`;`)();

describe('escapeForTemplateLiteral', () => {
  it.each([
    ['backslash', 'a\\b\\\\c \\n literal'],
    ['backtick', 'use `code` here'],
    ['dollar-brace', 'price ${amount} and $ alone and {braces}'],
    ['all three together', 'x\\`y${z}\\${w}`'],
    ['plain text', 'nothing special'],
    ['empty', ''],
  ])('round-trips a string with %s', (_label, raw) => {
    expect(evalTemplate(escapeForTemplateLiteral(raw))).toBe(raw);
  });

  it('escapes the backslash before the backtick so the added backslash is not doubled', () => {
    expect(escapeForTemplateLiteral('`')).toBe('\\`');
    expect(escapeForTemplateLiteral('\\')).toBe('\\\\');
    expect(escapeForTemplateLiteral('${')).toBe('\\${');
  });
});

describe('main (sandboxed)', () => {
  let tmp;
  let docsDir;
  let outPath;
  let logSpy;

  const writeAllSources = (overrides = {}) => {
    for (const { file } of SOURCES) {
      fs.writeFileSync(
        path.join(docsDir, file),
        overrides[file] ?? `# synthetic ${file}\n\nbody with \`tick\` and \${x} and \\back\n`
      );
    }
  };

  beforeEach(() => {
    tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'legal-gen-'));
    docsDir = path.join(tmp, 'docs');
    outPath = path.join(tmp, 'out', 'nested', 'legalContent.generated.ts');
    fs.mkdirSync(docsDir);
    logSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    jest.restoreAllMocks();
    fs.rmSync(tmp, { recursive: true, force: true });
  });

  it('writes one exported string constant per source, creating missing output directories', () => {
    writeAllSources();
    main({ docsDir, outPath });

    const out = fs.readFileSync(outPath, 'utf8');
    expect(out.startsWith('// AUTO-GENERATED by scripts/generate-legal-content.js')).toBe(true);
    for (const { key } of SOURCES) {
      expect(out).toContain(`export const ${key}: string = \``);
    }
    expect(logSpy).toHaveBeenCalledTimes(1);
  });

  it('emits content that evaluates back to the exact source text', () => {
    const tricky = 'line one\n`tick` ${x} \\back\n';
    writeAllSources({ [SOURCES[0].file]: tricky });
    main({ docsDir, outPath });

    const out = fs.readFileSync(outPath, 'utf8');
    const re = new RegExp(`export const ${SOURCES[0].key}: string = \`([\\s\\S]*?)\`;\\n`);
    const body = out.match(re)[1];
    expect(evalTemplate(body)).toBe(tricky);
  });

  it('throws naming the file when a source is missing', () => {
    writeAllSources();
    fs.rmSync(path.join(docsDir, SOURCES[2].file));
    expect(() => main({ docsDir, outPath })).toThrow(/Missing legal source: .*medical-disclaimer\.md/);
    expect(fs.existsSync(outPath)).toBe(false);
  });

  it('does not rewrite the output when the input is unchanged', () => {
    writeAllSources();
    main({ docsDir, outPath });
    const before = fs.statSync(outPath).mtimeMs;

    const writeSpy = jest.spyOn(fs, 'writeFileSync');
    logSpy.mockClear();
    main({ docsDir, outPath });

    expect(writeSpy).not.toHaveBeenCalled();
    expect(logSpy).not.toHaveBeenCalled();
    expect(fs.statSync(outPath).mtimeMs).toBe(before);
  });

  it('rewrites the output when a source changes', () => {
    writeAllSources();
    main({ docsDir, outPath });
    const first = fs.readFileSync(outPath, 'utf8');

    writeAllSources({ [SOURCES[1].file]: 'changed synthetic body\n' });
    main({ docsDir, outPath });

    const second = fs.readFileSync(outPath, 'utf8');
    expect(second).not.toBe(first);
    expect(second).toContain('changed synthetic body');
  });
});
